<div class="row justify-content-center"><div class="col-md-9 col-lg-7"><section class="hero-card p-4 p-md-5"><a class="small text-success text-decoration-none" href="/movimientos">← Volver a movimientos</a><h1 class="h2 fw-bold mt-3"><?= $editing ? 'Editar movimiento' : 'Nuevo movimiento' ?></h1>
<?php if (!$categories): ?><div class="alert alert-warning">Primero debes <a href="/categorias/nueva">crear una categoría</a>.</div><?php endif; ?>
<?php if ($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="post" action="<?= $editing ? '/movimientos/actualizar' : '/movimientos' ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><?php if ($editing): ?><input type="hidden" name="id" value="<?= (int) ($movement['id'] ?? 0) ?>"><?php endif; ?>
<div class="mb-3"><label class="form-label" for="tipo">Tipo</label><select class="form-select" id="tipo" name="tipo" required><option value="">Selecciona</option><option value="ingreso" <?= ($movement['tipo'] ?? '') === 'ingreso' ? 'selected' : '' ?>>Ingreso</option><option value="gasto" <?= ($movement['tipo'] ?? '') === 'gasto' ? 'selected' : '' ?>>Gasto</option></select></div>
<div class="mb-3"><label class="form-label" for="categoria_id">Categoría</label><select class="form-select" id="categoria_id" name="categoria_id" required><option value="">Selecciona</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" data-type="<?= htmlspecialchars($category['tipo'], ENT_QUOTES, 'UTF-8') ?>" <?= (string) ($movement['categoria_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= htmlspecialchars($category['nombre'], ENT_QUOTES, 'UTF-8') ?> (<?= $category['tipo'] === 'ingreso' ? 'Ingreso' : 'Gasto' ?>)</option><?php endforeach; ?></select></div>
<div class="mb-3"><label class="form-label" for="monto">Valor</label><div class="input-group"><span class="input-group-text">$</span><input class="form-control" id="monto" name="monto" type="number" min="0.01" max="99999999999.99" step="0.01" required value="<?= htmlspecialchars((string) ($movement['monto'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></div></div>
<div class="mb-3"><label class="form-label" for="descripcion">Descripción <span class="text-secondary">(opcional)</span></label><input class="form-control" id="descripcion" name="descripcion" maxlength="255" value="<?= htmlspecialchars((string) ($movement['descripcion'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></div>
<div class="mb-4"><label class="form-label" for="fecha">Fecha</label><input class="form-control" id="fecha" name="fecha" type="date" required value="<?= htmlspecialchars((string) ($movement['fecha'] ?? date('Y-m-d')), ENT_QUOTES, 'UTF-8') ?>"></div>
<button class="btn btn-success" type="submit" <?= !$categories ? 'disabled' : '' ?>><?= $editing ? 'Guardar cambios' : 'Registrar movimiento' ?></button> <a class="btn btn-outline-secondary" href="/movimientos">Cancelar</a></form></section></div></div>
<script>const tipo=document.getElementById('tipo'), categoria=document.getElementById('categoria_id');function filtrarCategorias(){for(const option of categoria.options){if(option.value)option.hidden=tipo.value!==''&&option.dataset.type!==tipo.value;}if(categoria.selectedOptions[0]?.hidden)categoria.value='';}tipo.addEventListener('change',filtrarCategorias);filtrarCategorias();</script>
